// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    receive() external payable {}

    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1, 1e30);
        // c must hold enough Ether for the transfer
        vm.deal(address(c), amount);
        // owner of c is this test contract (msg.sender at setUp), so
        // c.withdraw transfers to this contract
        uint256 ownerBefore = address(this).balance;
        uint256 cBefore = address(c).balance;
        c.withdraw(amount);
        // Rule: the caller receives exactly the requested amount from c.
        assertTrue(address(this).balance == ownerBefore + amount && address(c).balance == cBefore - amount);
    }
}
